<div class="form-grid"><label>Nombre<input name="name" value="{{ old('name',$user->name ?? '') }}" required maxlength="150" autocomplete="name"></label><label>Correo electrónico<input name="email" type="email" value="{{ old('email',$user->email ?? '') }}" required autocomplete="email"></label><label>Rol técnico<select name="role">@foreach(\App\Models\User::ROLES as $role)<option @selected(old('role',$user->role ?? 'consultor')===$role)>{{ str_replace('_',' ',$role) }}</option>@endforeach</select></label><label>Estado<select name="active"><option value="1" @selected((string)old('active',isset($user)?(int)$user->active:1)==='1')>Activo</option><option value="0" @selected((string)old('active',isset($user)?(int)$user->active:1)==='0')>Suspendido</option></select></label><label>Contraseña {{ isset($user) ? '(vacía para conservar)' : '(mínimo 12 caracteres)' }}<input name="password" type="password" minlength="12" @required(!isset($user)) autocomplete="new-password"></label><label>Repetir contraseña<input name="password_confirmation" type="password" minlength="12" @required(!isset($user)) autocomplete="new-password"></label></div>
